<span class="line"><span style="color:#E06C75;">                lo</span><span style="color:#56B6C2;"> =</span><span style="color:#E06C75;"> mid</span><span style="color:#56B6C2;"> +</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">;        </span><span style="color:#7F848E;font-style:italic;">// 目标在右半部分，收缩左边界</span></span>
